# browser — browser-artifact discovery (kinds, sizes, mtimes only). History/
# places are sqlite: acquire via ircollect, parse OFFLINE with browser_parse.py.
$CH=@('Local\Google\Chrome','Local\Microsoft\Edge','Local\BraveSoftware\Brave-Browser','Local\Vivaldi')
$U=@();try{foreach($d in (Get-ChildItem 'C:\Users' -Directory -ErrorAction Stop)){foreach($g in $CH){$ud=Join-Path $d.FullName ($g+'\User Data');if(Test-Path $ud){foreach($p in (Get-ChildItem $ud -Directory -ErrorAction SilentlyContinue)){foreach($f in @('History','Archived History','Bookmarks','Web Data')){$fp=Join-Path $p.FullName $f;if(Test-Path $fp -and $U.Count -lt $Limit){$i=Get-Item $fp;$U+=[pscustomobject]@{user=$d.Name;browser=($g -split '\\')[-1];profile=$p.Name;kind=$f.ToLower();size=$i.Length;mtime=($i.LastWriteTimeUtc.ToString('o'))}}}}}}}}catch{}
$F=@();try{foreach($d in (Get-ChildItem 'C:\Users' -Directory -ErrorAction SilentlyContinue)){$pd=Join-Path $d.FullName 'AppData\Roaming\Mozilla\Firefox\Profiles';if(Test-Path $pd){foreach($p in (Get-ChildItem $pd -Directory -ErrorAction SilentlyContinue)){foreach($f in @('places.sqlite','cookies.sqlite','formhistory.sqlite')){$fp=Join-Path $p.FullName $f;if(Test-Path $fp -and $F.Count -lt $Limit){$i=Get-Item $fp;$F+=[pscustomobject]@{user=$d.Name;profile=$p.Name;kind=$f;size=$i.Length;mtime=($i.LastWriteTimeUtc.ToString('o'))}}}}}}}catch{}
[pscustomobject]@{skill='browser';host=$env:COMPUTERNAME;utc=(Get-Date).ToUniversalTime().ToString('o');chromium=$U;firefox=$F;offline_parse='browser_parse.py on the ircollect copy'}|ConvertTo-Json -Compress -Depth 4
